// FuncSupport describes how LynxDB executes one PPL function name.
type FuncSupport struct {
	// Name is the PPL function name.
	Name string
	// IR is the registry function the name maps onto; empty for names
	// lowered to IR operators or not supported.
	IR string
	// Lowering names the IR construct for names lowered to operators.
	Lowering string
	// Unsupported explains why LynxDB does not execute the function.
	Unsupported string
	lower       func(x *ectx, n *ast.Call) (ir.Expr, error)
}

// The PPL scalar function catalog: every PPL function name, mapped to an IR
// registry function, to a lowering onto IR operators, or to the reason it is
// unsupported. Aggregation names live in aggregateCatalog.
var scalarCatalog = map[string]*FuncSupport{}

func direct(name, irName string) {
	scalarCatalog[name] = &FuncSupport{Name: name, IR: irName}
}

func lowered(name, construct string, f func(x *ectx, n *ast.Call) (ir.Expr, error)) {
	scalarCatalog[name] = &FuncSupport{Name: name, Lowering: construct, lower: f}
}

func unsupportedFunc(reason string, names ...string) {
	for _, n := range names {
		scalarCatalog[n] = &FuncSupport{Name: n, Unsupported: reason}
	}
}

// ScalarFunctions lists the PPL scalar function catalog sorted by name.
func ScalarFunctions() []FuncSupport {
	out := make([]FuncSupport, 0, len(scalarCatalog))
	for _, f := range scalarCatalog {
		out = append(out, *f)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out
}

